import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const source=readFileSync(new URL('../web/src/features/Approvals.words.ts',import.meta.url),'utf8');
const body=source.match(/export function askerOf\([^\n]+\{\n([\s\S]*?)\n\}/)?.[1];
assert.ok(body,'actual approval-card attribution source');
const mine={person:'owner',label:'Sergey',address:'admin/phone',devices:[{address:'admin/laptop'}]};
const owns=(p,address)=>p?.address===address||p?.devices?.some(d=>d.address===address);
const asker=new Function('m','o','names','dm','isThreadMsg','isMine','personName','niceDevice','agentName','agentWhere',body);
const overview={me:{address:'admin/laptop'},person:mine};
const agent={pid:'source-pid',agent_id:'codex-id',host:{...mine,address:'admin/laptop'}};
const dm={kind:'group',agents:[agent],members:[mine]};
const call=m=>asker(m,overview,{'codex-id':'Codex'},dm,()=>false,(a,o)=>owns(o.person,a),p=>p.label,a=>a, (id,n)=>n[id]||'Your agent',()=> 'Your agent · Laptop');
const child={id:'child',pid:'target-pid',agent_author_pid:'source-pid',verified_agent:true,from:'admin/laptop',dir:'out',kind:'question'};
const result=call(child);
assert.equal(result.agent,true,'verified own-host child is an agent request');
assert.equal(result.you,false,'an agent host is not its human owner');
assert.equal(result.name,'Codex');
assert.equal(result.seed,'codex-id');
assert.equal(call({...child,agent_author_pid:undefined,verified_agent:false}).you,true,'own human request remains You');
assert.equal(call({...child,from:'impostor/host'}).agent,false,'author participation must match the actual host');
assert.equal(call({...child,verified_agent:false}).agent,false,'claimed PID alone is not verification');
console.log('PASS request author: verified own agent, own human, mismatched host, unverified PID');
